-- name 普通投资者专业投资者统计
-- type Spark SQL
-- author admin@dtstack.com
-- create time 2023-01-18 09:04:58
-- desc 

-- 1.普通投资者
select count(1) from trcif.cif_tkhywsx a,trcif.cif_tkhxx b where a.khh=b.khh and (b.khzt not in (3,6,7) or (b.khzt=3 and b.xhrq>'20221231')) and a.tzzfl=0;

-- 2.专业投资者
select count(1) from trcif.cif_tkhywsx a,trcif.cif_tkhxx b where a.khh=b.khh and (b.khzt not in (3,6,7) or (b.khzt=3 and b.xhrq>'20221231')) and a.tzzfl in ('1','2','3');

-- 3.普通转专业
-- 方法一
-- 认定专业投资者业务请求
select count(1) from trcif.cif_tywqq  where ywdm='20035' and clzt=8 and tx_date >=20220101 and tx_date <20230101;
select count(1) from trcif.cifhis_tywqq  where ywdm='20035' and clzt=8 and tx_date >=20220101 and tx_date <20230101;
-- 方法二
select * from trcif.cif_tkhywsx where tzzpdrq >=20220101 and tzzpdrq <20230101  and tzzpdyxq>=20230101 and tzzfl in (1,2,3);

-- 4.专业转普通
-- 方法一 取消+过期
-- 取消专业投资者业务请求
select count(1) from trcif.cif_tywqq  where ywdm='20036' and clzt=8 and sqrq >=20220101 and sqrq <20230101;
select count(1) from trcif.cifhis_tywqq  where ywdm='20036' and clzt=8 and tx_date >=20220101 and tx_date <20230101;
-- 过期查操作明细

-- 方法二
-- 查询业务属性有效期过期的
select * from trcif.cif_tkhywsx where tzzpdyxq >=20220101 and tzzpdyxq <20230101 and tzzfl =0;

