select khh,avg(ZZC-zfz) zzc_avg from adp_dm.ids_t_stat_zd_r group by khh
) T WHERE T.zzc_avg>=10000000 and T.zzc_avg<50000000
union all
--5000-10000万 永久  
SELECT '5000-1亿' as range_zc,COUNT(1) FROM (
select khh,avg(ZZC-zfz) zzc_avg from adp_dm.ids_t_stat_zd_r group by khh
) T WHERE T.zzc_avg>=50000000 and T.zzc_avg<100000000
union all
--1亿以上 永久 
SELECT '1亿以上' as range_zc,COUNT(1) FROM (
select khh,avg(ZZC-zfz) zzc_avg from adp_dm.ids_t_stat_zd_r group by khh
) T WHERE T.zzc_avg>=100000000;

